62	+// configureFlowDeps contains side effects used by the interactive configure
63	+// flow. Tests can replace individual operations without a keyring, browser,
64	+// GitHub CLI, or live control plane.
65	+type configureFlowDeps struct {
66	+	resolveAuth  func(context.Context) (statusTarget, error)
67	+	fetchProfile profileFetcher
68	+	runLogin     func(context.Context, io.Writer, io.Writer) error
69	+	accessClient func(context.Context) (configureAccessReporter, error)
70	+	coreClient   func() (*coreapi.Client, error)
