76	+func newConfigureFlowDeps(insecure bool) configureFlowDeps {
77	+	return configureFlowDeps{
78	+		resolveAuth: func(ctx context.Context) (statusTarget, error) {
79	+			return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
80	+		},
81	+		fetchProfile: defaultFetchProfile,
82	+		runLogin: func(ctx context.Context, outW, errW io.Writer) error {
83	+			cmd := newLoginCmd()
84	+			cmd.SetContext(ctx)
85	+			cmd.SetOut(outW)
86	+			cmd.SetErr(errW)
87	+			return cmd.RunE(cmd, nil)
88	+		},
89	+		accessClient: func(ctx context.Context) (configureAccessReporter, error) {
90	+			return NewAuthenticatedAPIClient(ctx, insecure)
91	+		},
92	+		coreClient:  coreapi.New,
93	+		openURL:     openBrowser,
94	+		githubAdmin: configureGitHubAdmin,
95	+		now:         time.Now,
