99	+// runConfigureOnboarding is a seam for command tests. Bare interactive
100	+// `entire configure` is the new end-to-end entry point; flag-based configure
101	+// remains the non-interactive settings editor.
102	+var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
103	+	return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
104	+}
