106	+func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
107	+	cmd.SilenceUsage = true
108	+	ctx := cmd.Context()
109	+	outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
110	+
111	+	repoRoot, err := paths.WorktreeRoot(ctx)
112	+	if err != nil {
113	+		fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
114	+		return NewSilentError(errors.New("not a git repository"))
115	+	}
116	+	owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
117	+	if err != nil {
118	+		return err
119	+	}
120	+
121	+	profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
122	+	if err != nil {
123	+		return err
124	+	}
125	+
126	+	reporter, err := deps.accessClient(ctx)
127	+	if err != nil {
128	+		return fmt.Errorf("connect to Entire: %w", err)
129	+	}
130	+	access, err := reporter.ReportEnable(ctx, cleanRemote)
131	+	if err != nil {
132	+		return fmt.Errorf("check repository access: %w", err)
133	+	}
134	+	if !access.Connected {
135	+		if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, deps); err != nil {
136	+			return err
137	+		}
138	+	}
139	+
140	+	client, err := deps.coreClient()
141	+	if err != nil {
142	+		return fmt.Errorf("connect to Entire control plane: %w", err)
143	+	}
144	+	placements, err := resolvePullablePlacements(ctx, client, owner, repo)
145	+	if err != nil {
146	+		return renderCoreError(err)
147	+	}
148	+	if len(placements) == 0 {
149	+		placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction)
150	+		if err != nil {
151	+			return err
152	+		}
153	+	}
154	+	if len(placements) == 0 {
155	+		return errors.New("no usable mirror was selected")
156	+	}
157	+
158	+	manageRegionsHint := ""
159	+	if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
160	+		manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
161	+			configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
162	+	}
163	+	initialChanges, err := configureGitChanges(ctx, repoRoot)
164	+	if err != nil {
165	+		return err
166	+	}
167	+	branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
168	+	if branchErr != nil {
169	+		// Best-effort: local-only saves do not need a branch.
170	+		branch = ""
171	+	}
172	+	protected := false
173	+	if branch != "" {
174	+		if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
175	+			// Advisory only; git push remains authoritative.
176	+			protected = detected
177	+		}
178	+	}
179	+	branchPushSafe := false
180	+	if branch != "" && len(initialChanges) == 0 {
181	+		branchPushSafe = configureBranchHasNoUnpushedCommits(ctx, repoRoot)
182	+	}
183	+	chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
184	+		ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
185	+		branch, protected, branchPushSafe,
186	+	)
187	+	if err != nil {
188	+		return err
189	+	}
190	+	if saveChoice == configureSaveCancel {
191	+		fmt.Fprintln(outW, "Configuration cancelled.")
192	+		return nil
193	+	}
194	+	if saveChoice == "" {
195	+		fmt.Fprintln(outW, "No configuration changes.")
196	+		return nil
197	+	}
198	+
199	+	// Snapshot immediately before applying our changes. The form may have been
200	+	// open for an arbitrary amount of time, so the pre-form status is not a safe
201	+	// commit baseline: editor autosaves or another process may have changed files
202	+	// while the user was choosing options. Anything already dirty now is excluded
203	+	// from generated and disables automatic commit/push below.
204	+	beforeApply, err := configureGitChanges(ctx, repoRoot)
205	+	if err != nil {
206	+		return err
207	+	}
208	+	if (saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch) &&
209	+		(len(beforeApply) != 0 || !configureBranchHasNoUnpushedCommits(ctx, repoRoot)) {
210	+		saveChoice = configureSaveLocal
211	+	}
212	+
213	+	forgeRemote, err := configureUseMirror(ctx, outW, errW, repoRoot, owner, repo, chosen)
214	+	if err != nil {
215	+		return err
216	+	}
217	+
218	+	if agentsChanged {
219	+		opts = configureOnboardingEnableOptions(opts)
220	+		if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
221	+			return err
222	+		}
223	+		// A local enabled:false override must not win over the newly written project
224	+		// configuration. setEnabledFlag updates the project and synchronizes an
225	+		// existing local override without replacing its other local-only fields.
226	+		if err := setEnabledFlag(ctx, true, true); err != nil {
227	+			return err
228	+		}
229	+	}
230	+
231	+	after, err := configureGitChanges(ctx, repoRoot)
232	+	if err != nil {
233	+		return err
234	+	}
235	+	generated := newConfigureChanges(beforeApply, after)
236	+	if agentsChanged {
237	+		fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
238	+	}
239	+
240	+	if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
241	+		if err := configureSaveAndPush(cmd, repoRoot, owner, repo, beforeApply, generated, branch, protected, saveChoice, forgeRemote, deps.now); err != nil {
242	+			return err
243	+		}
244	+	} else if agentsChanged && len(generated) > 0 {
245	+		fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
246	+	}
247	+	fmt.Fprintln(outW, "✓ Configuration complete")
248	+	fmt.Fprintln(outW)
249	+	fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
250	+	fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
251	+	return nil
252	+}
