254	+func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
255	+	opts.Yes = true
256	+	opts.UseProjectSettings = true
257	+	opts.UseLocalSettings = false
258	+	opts.SuppressDoneMessage = true
259	+	opts.SuppressAdditionalSetup = true
260	+	// Logged-in onboarding does not ask a separate telemetry question. The
261	+	// documented default is applied without prompting; existing settings and
262	+	// ENTIRE_TELEMETRY_OPTOUT remain authoritative.
263	+	return opts
264	+}
