270	+func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
271	+	raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
272	+	if err != nil {
273	+		return "", "", "", fmt.Errorf("read origin remote: %w", err)
274	+	}
275	+	info, err := gitremote.ParseURL(raw)
276	+	if err != nil {
277	+		return "", "", "", fmt.Errorf("parse origin remote: %w", err)
278	+	}
279	+	if info.Forge != mirrorUseForge {
280	+		return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
281	+	}
282	+	clean, err := cleanRemoteURLForReport(raw)
283	+	if err != nil {
284	+		return "", "", "", err
285	+	}
286	+	return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
287	+}
