289	+func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
290	+	target, err := deps.resolveAuth(ctx)
291	+	if err != nil {
292	+		return nil, err
293	+	}
294	+	if target.token != "" {
295	+		if err := api.RequireSecureURL(target.coreURL); err != nil {
296	+			return nil, fmt.Errorf("context login server URL check: %w", err)
297	+		}
298	+		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
299	+			return profile, nil
300	+		} else if !isKeychainTokenRejected(profileErr) {
301	+			return nil, fmt.Errorf("validate login: %w", profileErr)
302	+		}
303	+	}
304	+
305	+	if err := deps.runLogin(ctx, outW, errW); err != nil {
306	+		return nil, fmt.Errorf("login: %w", err)
307	+	}
308	+	target, err = deps.resolveAuth(ctx)
309	+	if err != nil {
310	+		return nil, err
311	+	}
312	+	if target.token == "" {
313	+		return nil, errors.New("login completed without an active session")
314	+	}
315	+	if err := api.RequireSecureURL(target.coreURL); err != nil {
316	+		return nil, fmt.Errorf("context login server URL check: %w", err)
317	+	}
318	+	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
319	+	if err != nil {
320	+		return nil, fmt.Errorf("validate login: %w", err)
321	+	}
322	+	fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
323	+	return profile, nil
324	+}
