326	+func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
327	+	fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
328	+	installURL := strings.TrimSpace(initial.InstallURL)
329	+	if installURL == "" {
330	+		installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
331	+	}
332	+
333	+	admin, adminErr := deps.githubAdmin(ctx, owner, repo)
334	+	if adminErr == nil && !admin {
335	+		fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
336	+		fmt.Fprintln(errW, "  Send them this link to continue:")
337	+		fmt.Fprintf(errW, "\n  %s\n", installURL)
338	+		return NewSilentError(errors.New("GitHub app installation required"))
339	+	}
340	+	if adminErr != nil {
341	+		switch {
342	+		case errors.Is(adminErr, errConfigureGHUnavailable):
343	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
344	+			fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
345	+		case errors.Is(adminErr, errConfigureGHUnauthenticated):
346	+			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
347	+			fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
348	+		default:
349	+			fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
350	+		}
351	+		fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
352	+		fmt.Fprintln(errW)
353	+	}
354	+
355	+	fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
356	+	fmt.Fprintf(outW, "  %s\n\n", installURL)
357	+	if err := deps.openURL(ctx, installURL); err != nil {
358	+		fmt.Fprintln(outW, "  Open the link above in your browser.")
359	+	}
360	+	stop := startSpinner(errW, "Waiting for installation")
361	+	stopped := false
362	+	defer func() {
363	+		if !stopped {
364	+			stop(false)
365	+		}
366	+	}()
367	+
368	+	waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
369	+	defer cancel()
370	+	ticker := time.NewTicker(configureAccessPollInterval)
371	+	defer ticker.Stop()
372	+	for {
373	+		select {
374	+		case <-waitCtx.Done():
375	+			return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
376	+		case <-ticker.C:
377	+			access, err := reporter.ReportEnable(waitCtx, cleanRemote)
378	+			if err == nil && access.Connected {
379	+				stop(true)
380	+				stopped = true
381	+				fmt.Fprintln(outW, "✓ Access granted")
382	+				return nil
383	+			}
384	+		}
385	+	}
386	+}
