388	+func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
389	+	runner := execRunner{}
390	+	if !ghAvailable(ctx, runner) {
391	+		return false, errConfigureGHUnavailable
392	+	}
393	+	if !ghAuthenticated(ctx, runner) {
394	+		return false, errConfigureGHUnauthenticated
395	+	}
396	+	out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
397	+	if err != nil {
398	+		return false, fmt.Errorf("check GitHub admin permission: %w", err)
399	+	}
400	+	admin, err := strconv.ParseBool(strings.TrimSpace(out))
401	+	if err != nil {
402	+		return false, fmt.Errorf("parse GitHub admin permission: %w", err)
403	+	}
404	+	return admin, nil
405	+}
