407	+func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string) ([]coreapi.ResolvedPlacement, error) {
408	+	regions, err := availableRegions(ctx, client)
409	+	if err != nil {
410	+		return nil, fmt.Errorf("list regions: %w", err)
411	+	}
412	+	if len(regions) == 0 {
413	+		return nil, errors.New("no regions available to mirror into")
414	+	}
415	+	selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction)
416	+	if err != nil {
417	+		return nil, err
418	+	}
419	+	results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
420	+	reportErr := reportMirrorResults(outW, errW, results)
421	+	placements := configureSuccessfulMirrorPlacements(selected, results)
422	+	if len(placements) > 0 {
423	+		if reportErr != nil {
424	+			fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
425	+		}
426	+		return placements, nil
427	+	}
428	+	if reportErr != nil {
429	+		return nil, reportErr
430	+	}
431	+	return nil, errors.New("no usable mirrors were created")
432	+}
433	+
434	+func configureSuccessfulMirrorPlacements(selected []regionChoice, results []mirrorResult) []coreapi.ResolvedPlacement {
435	+	placements := make([]coreapi.ResolvedPlacement, 0, len(results))
436	+	for i, result := range results {
437	+		if i >= len(selected) || result.err != nil || result.cloneURL == "" {
438	+			continue
439	+		}
440	+		region := selected[i]
441	+		placements = append(placements, coreapi.ResolvedPlacement{
442	+			ClusterHost:  region.host,
443	+			Cell:         coreapi.NewOptString(region.slug),
444	+			Jurisdiction: coreapi.NewOptString(region.jurisdiction),
445	+		})
446	+	}
447	+	return placements
448	+}
449	+
450	+func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string) ([]regionChoice, error) {
451	+	opts, defaults := clusterChoices(regions, jurisdiction)
452	+	byHost := make(map[string]regionChoice, len(regions))
453	+	for _, region := range regions {
454	+		byHost[region.host] = region
455	+	}
456	+	selected := append([]string(nil), defaults...)
457	+	form := NewAccessibleForm(huh.NewGroup(
458	+		huh.NewMultiSelect[string]().
459	+			Title("Which regions should this repository live in?").
460	+			Description("Space to select, enter to confirm — your data stays in the selected regions.").
461	+			Options(opts...).
462	+			Height(multiSelectHeight(len(opts))).
463	+			Validate(func(values []string) error {
464	+				if len(values) == 0 {
465	+					return errors.New("select at least one region")
466	+				}
467	+				return nil
468	+			}).
469	+			Value(&selected),
470	+	))
471	+	if err := form.RunWithContext(ctx); err != nil {
472	+		if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
473	+			return nil, cancelErr
474	+		}
475	+		return nil, NewSilentError(errors.New("configure cancelled"))
476	+	}
477	+	chosen := make([]regionChoice, 0, len(selected))
478	+	for _, host := range selected {
479	+		if region, ok := byHost[host]; ok {
480	+			chosen = append(chosen, region)
481	+		}
482	+	}
483	+	return chosen, nil
484	+}
