526	+func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
527	+	if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
528	+		switch {
529	+		case configureRadioSelectKey(keyMsg.String()):
530	+			field.commitHighlighted()
531	+			return field, configureWindowResize(field.window)
532	+		case configureNextKey(keyMsg.String()):
