654	+func sameStrings(a, b []string) bool {
655	+	if len(a) != len(b) {
656	+		return false
657	+	}
658	+	seen := make(map[string]int, len(a))
659	+	for _, value := range a {
660	+		seen[value]++
661	+	}
662	+	for _, value := range b {
663	+		seen[value]--
664	+		if seen[value] < 0 {
665	+			return false
666	+		}
667	+	}
668	+	return true
