1078	+		if isBuiltInAgent(detected) {
1079	+			selected[detected.Name()] = struct{}{}
1080	+		}
1081	+	}
1082	+	return selected
1083	+}
1084	+
1085	+func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1086	+	remotes, err := listGitRemotes(ctx, repoRoot)
1087	+	if err != nil {
1088	+		return "", err
1089	+	}
1090	+	current := ""
1091	+	if remotes[defaultMirrorRemote] {
1092	+		current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1093	+		if err != nil {
1094	+			return "", fmt.Errorf("read origin remote URL: %w", err)
1095	+		}
1096	+	}
1097	+
1098	+	forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1099	+	if err != nil {
1100	+		return "", err
1101	+	}
1102	+	preserve := ""
1103	+	if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1104	+		if forgeRemote == "" {
1105	+			preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1106	+			forgeRemote = preserve
1107	+		}
1108	+	}
1109	+	if forgeRemote == "" {
1110	+		forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1111	+		forgeURL := fmt.Sprintf("https://github.com/%s/%s.git", owner, repo)
1112	+		if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1113	+			return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1114	+		}
1115	+		remotes[forgeRemote] = true
1116	+		fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1117	+	}
1118	+
1119	+	mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1120	+	plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1121	+	if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1122	+		return "", err
1123	+	}
1124	+	// Report the replaced URL and where it remains reachable. The returned
1125	+	// forgeRemote is deliberately separate from the mirror fetch remote: config
1126	+	// commits must land on GitHub, never in the one-way Entire mirror.
1127	+	reportMirrorRemotePlan(outW, errW, plan)
1128	+	return forgeRemote, nil
1129	+}
1130	+
1131	+func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1132	+	names := make([]string, 0, len(remotes))
1133	+	for name := range remotes {
1134	+		if name != exclude {
1135	+			names = append(names, name)
1136	+		}
1137	+	}
1138	+	sort.SliceStable(names, func(i, j int) bool {
1139	+		priority := func(name string) int {
1140	+			switch name {
1141	+			case mirrorCloneProviderGitHub:
1142	+				return 0
1143	+			case defaultMirrorUpstreamRemote:
1144	+				return 1
1145	+			default:
1146	+				return 2
1147	+			}
1148	+		}
1149	+		if priority(names[i]) != priority(names[j]) {
1150	+			return priority(names[i]) < priority(names[j])
1151	+		}
1152	+		return names[i] < names[j]
1153	+	})
1154	+	for _, name := range names {
1155	+		raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1156	+		if err != nil {
1157	+			return "", fmt.Errorf("read remote %q URL: %w", name, err)
1158	+		}
1159	+		info, err := gitremote.ParseURL(raw)
1160	+		if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1161	+			strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1162	+			return name, nil
1163	+		}
1164	+	}
1165	+	return "", nil
1166	+}
1167	+
1168	+func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
1169	+	for _, candidate := range candidates {
1170	+		if !remotes[candidate] {
1171	+			return candidate
1172	+		}
1173	+	}
1174	+	for i := 2; ; i++ {
1175	+		candidate := fmt.Sprintf("github-%d", i)
1176	+		if !remotes[candidate] {
1177	+			return candidate
1178	+		}
1179	+	}
1180	+}
1181	+
1182	+// configureGitChanges returns porcelain status keyed by path. Its values retain
1183	+// XY so callers can detect whether anything was already staged before the flow.
1184	+func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1185	+	out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1186	+	if err != nil {
1187	+		return nil, fmt.Errorf("read git status: %w", err)
1188	+	}
1189	+	changes := make(map[string]string)
1190	+	for _, line := range strings.Split(out, "\n") {
1191	+		if len(line) < 4 {
1192	+			continue
1193	+		}
1194	+		path := strings.TrimSpace(line[3:])
1195	+		if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1196	+			path = path[arrow+4:]
1197	+		}
1198	+		if path != "" {
1199	+			changes[path] = line[:2]
1200	+		}
1201	+	}
1202	+	return changes, nil
1203	+}
1204	+
1205	+func newConfigureChanges(before, after map[string]string) []string {
1206	+	paths := make([]string, 0, len(after))
1207	+	for path := range after {
1208	+		if _, existed := before[path]; !existed {
1209	+			paths = append(paths, path)
1210	+		}
1211	+	}
1212	+	sort.Strings(paths)
1213	+	return paths
1214	+}
1215	+
1216	+func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1217	+	outW := cmd.OutOrStdout()
1218	+	if len(generated) == 0 {
1219	+		fmt.Fprintln(outW, "  No new configuration changes to commit.")
1220	+		return nil
1221	+	}
1222	+	if len(before) != 0 {
1223	+		fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1224	+		fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1225	+		return nil
1226	+	}
1227	+
1228	+	if branch == "" {
1229	+		return errors.New("cannot save configuration from a detached HEAD")
1230	+	}
1231	+	if protected && choice == configureSaveDirect {
1232	+		return fmt.Errorf("%s is protected; push to a new branch", branch)
1233	+	}
1234	+	if choice != configureSaveDirect && choice != configureSaveNewBranch {
1235	+		return fmt.Errorf("unknown save choice %q", choice)
1236	+	}
1237	+	if forgeRemote == "" {
1238	+		return errors.New("no GitHub remote available for configuration push")
1239	+	}
1240	+
1241	+	pushBranch := branch
1242	+	if choice == configureSaveNewBranch {
1243	+		var err error
1244	+		pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
1245	+		if err != nil {
1246	+			return err
1247	+		}
1248	+		if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1249	+			return fmt.Errorf("create configuration branch: %w", err)
1250	+		}
1251	+	}
1252	+
1253	+	args := []string{"add", "--"}
1254	+	args = append(args, generated...)
1255	+	if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1256	+		return fmt.Errorf("stage configuration: %w", err)
1257	+	}
1258	+	if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1259	+		return fmt.Errorf("commit configuration: %w", err)
1260	+	}
1261	+	sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1262	+	if err != nil {
1263	+		return fmt.Errorf("read configuration commit: %w", err)
1264	+	}
1265	+	fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1266	+	if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1267	+		return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1268	+	}
1269	+	fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1270	+	if choice == configureSaveNewBranch {
1271	+		fmt.Fprintln(outW, "  Open a trail to merge it:")
1272	+		fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1273	+	}
1274	+	return nil
1275	+}
1276	+
1277	+func configureBranchHasNoUnpushedCommits(ctx context.Context, repoRoot string) bool {
1278	+	// @{u} is the branch's configured upstream before configure rewrites any
1279	+	// remotes. If it does not exist, we cannot prove a direct push is isolated to
1280	+	// the generated config commit, so only the new-branch action is safe.
1281	+	upstream, err := gitRunner(ctx, repoRoot, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
1282	+	if err != nil || upstream == "" {
1283	+		return false
1284	+	}
1285	+	ahead, err := gitRunner(ctx, repoRoot, "rev-list", "--count", upstream+"..HEAD")
1286	+	if err != nil {
1287	+		return false
1288	+	}
1289	+	count, err := strconv.Atoi(strings.TrimSpace(ahead))
1290	+	return err == nil && count == 0
1291	+}
1292	+
1293	+func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1294	+	// GitHub's branch `.protected` flag is true for *any* active ruleset rule.
1295	+	// A non-blocking rule such as Copilot code review therefore made ordinary
1296	+	// feature branches look push-protected. Inspect the effective rules instead
1297	+	// and only require a new branch for rules that can reject a direct update.
1298	+	out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/rules/branches/"+url.PathEscape(branch)).Output()
1299	+	if err != nil {
1300	+		return false, fmt.Errorf("check GitHub branch rules: %w", err)
1301	+	}
1302	+	return configureRulesBlockDirectPush(out)
1303	+}
1304	+
1305	+func configureRulesBlockDirectPush(raw []byte) (bool, error) {
1306	+	var rules []struct {
1307	+		Type string `json:"type"`
1308	+	}
1309	+	if err := json.Unmarshal(raw, &rules); err != nil {
1310	+		return false, fmt.Errorf("parse GitHub branch rules: %w", err)
1311	+	}
1312	+	for _, rule := range rules {
1313	+		switch rule.Type {
1314	+		case "pull_request", "required_status_checks", "required_deployments", "update", "workflows":
1315	+			return true, nil
1316	+		}
1317	+	}
1318	+	return false, nil
1319	+}
1320	+
1321	+func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1322	+	candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1323	+	for _, candidate := range candidates {
1324	+		_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1325	+		if err == nil {
1326	+			continue // branch already exists
1327	+		}
1328	+		var exitErr *exec.ExitError
1329	+		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1330	+			return candidate, nil // show-ref uses 1 for a missing ref
1331	+		}
1332	+		return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1333	+	}
1334	+	return "", errors.New("could not choose an unused configuration branch name")
1335	+}
